Definition iarm_0RB1LC_1LA1RB_0RD0LC_1RD0LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LC_1LA1RB_0RD0LC_1RD0LA
  | 0, 1 => iarm0_1_0RB1LC_1LA1RB_0RD0LC_1RD0LA
  | 0, 2 => iarm0_2_0RB1LC_1LA1RB_0RD0LC_1RD0LA
  | 0, 3 => iarm0_3_0RB1LC_1LA1RB_0RD0LC_1RD0LA
  | _, _ => iarm0_0_0RB1LC_1LA1RB_0RD0LC_1RD0LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_0RB1LC_1LA1RB_0RD0LC_1RD0LA (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_0RB1LC_1LA1RB_0RD0LC_1RD0LA
  | 2, 0 => farm2_0_0RB1LC_1LA1RB_0RD0LC_1RD0LA
  | 3, 0 => farm3_0_0RB1LC_1LA1RB_0RD0LC_1RD0LA
  | _, _ => farm1_0_0RB1LC_1LA1RB_0RD0LC_1RD0LA  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_0RB1LC_1LA1RB_0RD0LC_1RD0LA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | 3, 0 => 1 | _, _ => 0 end.
Definition fm2_0RB1LC_1LA1RB_0RD0LC_1RD0LA (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 2, 0 => 1 | 3, 0 => 2 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_0RB1LC_1LA1RB_0RD0LC_1RD0LA (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => [SWinR 3]
  | 1, (StB, S0) => [SWinR 2]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWinR 4]
  | 1, (StC, S1) => [SWinR 13]
  | 1, (StD, S0) => [SWinR 15]
  | 1, (StD, S1) => [SWinR 5]
  | 2, (StA, S0) => []
  | 2, (StA, S1) => [SWinR 4]
  | 2, (StB, S0) => [SWinR 3]
  | 2, (StB, S1) => [SWin 1]
  | 2, (StC, S0) => [SWinR 6]
  | 2, (StC, S1) => [SWinR 5]
  | 2, (StD, S0) => [SWinR 7]
  | 2, (StD, S1) => [SWinR 8]
  | 3, (StA, S0) => [SWin 0]
  | 3, (StA, S1) => [SWin 3;SCycR 1;SWinR 2]
  | 3, (StB, S0) => [SWin 3;SCycR 1;SWinR 1]
  | 3, (StB, S1) => [SWin 1]
  | 3, (StC, S0) => [SWin 2]
  | 3, (StC, S1) => [SWin 3;SCycR 1;SWinR 2;SRotL 1;SWin 1]
  | 3, (StD, S0) => [SWin 3]
  | 3, (StD, S1) => [SWin 4]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
Definition vsegs_0RB1LC_1LA1RB_0RD0LC_1RD0LA (r : nat) (t : Instr) : list nseg :=
  match r, t with
  | 1, (StA, S0) => []
  | 1, (StA, S1) => []
  | 1, (StB, S0) => []
  | 1, (StB, S1) => []
  | 1, (StC, S0) => []
  | 1, (StC, S1) => []
  | 1, (StD, S0) => []
  | 1, (StD, S1) => []
  | 2, (StA, S0) => []
  | 2, (StA, S1) => []
  | 2, (StB, S0) => []
  | 2, (StB, S1) => []
  | 2, (StC, S0) => []
  | 2, (StC, S1) => []
  | 2, (StD, S0) => []
  | 2, (StD, S1) => []
  | 3, (StA, S0) => []
  | 3, (StA, S1) => []
  | 3, (StB, S0) => []
  | 3, (StB, S1) => []
  | 3, (StC, S0) => [NCh [RB (SWin 3);RB (SCycR 1);RB (SWinR 2);RB (SRotL 1);RB (SRotL 1);RB (SFoldL 1)]; NDn 1 [] [S0] 0 1 0 (mkS [] [] 0 0 []) (mkS [S1] [] 0 0 []) true]
  | 3, (StC, S1) => []
  | 3, (StD, S0) => [NCh [RB (SWin 3);RB (SCycR 1);RB (SWinR 2);RB (SRotL 1);RB (SRotL 1);RB (SFoldL 1)]; NDn 1 [] [S0] 0 1 0 (mkS [] [] 0 0 []) (mkS [S1] [] 0 0 []) true]
  | 3, (StD, S1) => [NCh [RB (SWin 3);RB (SCycR 1);RB (SWinR 2);RB (SRotL 1);RB (SRotL 1);RB (SFoldL 1)]; NDn 1 [] [S0] 0 1 0 (mkS [] [] 0 0 []) (mkS [S1] [] 0 0 []) true]
  | _, _ => []
  end.

Lemma iarm_reach_0RB1LC_1LA1RB_0RD0LC_1RD0LA : forall d r,
  d < fm_b FAM - 1 -> r < 3 + 1 ->
  ReachL tm (negb (fm_left FAM)) (fm_left FAM)
    (lr_lhs (iarm_0RB1LC_1LA1RB_0RD0LC_1RD0LA d r)) (lr_rhs (iarm_0RB1LC_1LA1RB_0RD0LC_1RD0LA d r)).
Proof.
  intros d r Hd Hr. vm_compute in Hd.
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_0RB1LC_1LA1RB_0RD0LC_1RD0LA | exact ok_iarm0_0_0RB1LC_1LA1RB_0RD0LC_1RD0LA]. }
    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_0RB1LC_1LA1RB_0RD0LC_1RD0LA | exact ok_iarm0_1_0RB1LC_1LA1RB_0RD0LC_1RD0LA]. }
    destruct r as [|r].
