  check_narm tm true false nrules iarm0_0_0RB1LC_1RC1RB_1LD1LA_0RC0LD ch_iarm0_0_0RB1LC_1RC1RB_1LD1LA_0RC0LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_0RB1LC_1RC1RB_1LD1LA_0RC0LD : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 [S0;S0]))
