Lemma bootl_0RB1LD_1LA1RC_1RB0LA_0RB0LA :
  stepn tm 8 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 8 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_0RB1LD_1LA1RC_1RB0LA_0RB0LA : NeverQuasiHaltsTr tm_0RB1LD_1LA1RC_1RB0LA_0RB0LA.
Proof.
  eapply (boardN_neverqhtr tm_0RB1LD_1LA1RC_1RB0LA_0RB0LA pins_0RB1LD_1LA1RC_1RB0LA_0RB0LA FAM 1
                           iarm_0RB1LD_1LA1RC_1RB0LA_0RB0LA 2 1
                           farm_0RB1LD_1LA1RC_1RB0LA_0RB0LA 2 1
                           fm1_0RB1LD_1LA1RC_1RB0LA_0RB0LA fm2_0RB1LD_1LA1RC_1RB0LA_0RB0LA 0
                           nrules vsegs_0RB1LD_1LA1RC_1RB0LA_0RB0LA vis_0RB1LD_1LA1RC_1RB0LA_0RB0LA
                           [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_0RB1LD_1LA1RC_1RB0LA_0RB0LA.
  - repeat constructor.
  - vm_compute; lia.
