Definition iarm_0RB1LD_1LA1RC_1RB0LD____0LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_0RB1LD_1LA1RC_1RB0LD____0LA
  | 0, 1 => iarm0_1_0RB1LD_1LA1RC_1RB0LD____0LA
  | 1, 0 => iarm1_0_0RB1LD_1LA1RC_1RB0LD____0LA
  | 1, 1 => iarm1_1_0RB1LD_1LA1RC_1RB0LD____0LA
  | 2, 0 => iarm2_0_0RB1LD_1LA1RC_1RB0LD____0LA
  | 2, 1 => iarm2_1_0RB1LD_1LA1RC_1RB0LD____0LA
  | _, _ => iarm0_0_0RB1LD_1LA1RC_1RB0LD____0LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

