          (mkC StA (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 [S1])) 4 6.
Definition ch_farm1_0_0RB1LD_1LA1RC_1RB0LD____0LA : list rstep := [RB (SWin 2);RB (SCycR 2);RB (SWinR 2);RB (SCycL 2 0);RB (SWin 2)].
