    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_0RB1LD_1LA1RC_1RB0LD____0LA | exact ok_iarm0_1_0RB1LD_1LA1RC_1RB0LD____0LA]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_0RB1LD_1LA1RC_1RB0LD____0LA | exact ok_iarm1_0_0RB1LD_1LA1RC_1RB0LD____0LA]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_0RB1LD_1LA1RC_1RB0LD____0LA | exact ok_iarm1_1_0RB1LD_1LA1RC_1RB0LD____0LA]. }
    exfalso; lia.
  }
  destruct d as [|d].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_0RB1LD_1LA1RC_1RB0LD____0LA | exact ok_iarm2_0_0RB1LD_1LA1RC_1RB0LD____0LA]. }
    destruct r as [|r].
