Lemma ok_farm1_0_0RB1LD_1RC0LA_1LA1RB_0RB0LA :
  check_narm tm true true nrules farm1_0_0RB1LD_1RC0LA_1LA1RB_0RB0LA ch_farm1_0_0RB1LD_1RC0LA_1LA1RB_0RB0LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm2_0_0RB1LD_1RC0LA_1LA1RB_0RB0LA : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1;S1] [S1;S1] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [S1;S0] 1 0 [S1;S0;S1;S1])) 0 1.
