Lemma vis_ok_0RB1LD_1RC0LA_1LA1RB_0RB0LA : forall r t, ~ In t pins_0RB1LD_1RC0LA_1LA1RB_0RB0LA -> 0 < r ->
  r < 2 + 1 ->
  nfire tm true true nrules (vsegs_0RB1LD_1RC0LA_1LA1RB_0RB0LA r t) (vis_0RB1LD_1RC0LA_1LA1RB_0RB0LA r t)
    (lr_lhs (farm_0RB1LD_1RC0LA_1LA1RB_0RB0LA r 0)) = Some t.
Proof.
  intros r t Hnp H0 Hr.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  exfalso; lia.
Qed.

Lemma bootl_0RB1LD_1RC0LA_1LA1RB_0RB0LA :
  stepn tm 4 InitES = Some (lift (fam_cfg FAM ([1], 0, 0))).
Proof.
  assert (H : match csteps tm 4 c0 with
              | Some c => ceqb c (fam_cfg FAM ([1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_0RB1LD_1RC0LA_1LA1RB_0RB0LA : NeverQuasiHaltsTr tm_0RB1LD_1RC0LA_1LA1RB_0RB0LA.
Proof.
  eapply (boardN_neverqhtr tm_0RB1LD_1RC0LA_1LA1RB_0RB0LA pins_0RB1LD_1RC0LA_1LA1RB_0RB0LA FAM 1
                           iarm_0RB1LD_1RC0LA_1LA1RB_0RB0LA 1 1
                           farm_0RB1LD_1RC0LA_1LA1RB_0RB0LA 2 1
                           fm1_0RB1LD_1RC0LA_1LA1RB_0RB0LA fm2_0RB1LD_1RC0LA_1LA1RB_0RB0LA 0
                           nrules vsegs_0RB1LD_1RC0LA_1LA1RB_0RB0LA vis_0RB1LD_1RC0LA_1LA1RB_0RB0LA
                           [1] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
