Definition fam_0RB1RC_0RC1RA_1LD1RB_0LA0LD : Fam := mkFam 4 [[S0;S0;S0];[S1;S1;S0];[S0;S0;S1];[S1;S1;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [1] 0] StC S1 false [].
