Definition rules_0RB1RC_0RC1RA_1LD1RB_0LA0LD : list LRule := map fst lad.
Local Notation rules := rules_0RB1RC_0RC1RA_1LD1RB_0LA0LD.

Lemma ladder_ok_0RB1RC_0RC1RA_1LD1RB_0LA0LD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_0RB1RC_0RC1RA_1LD1RB_0LA0LD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_0RB1RC_0RC1RA_1LD1RB_0LA0LD. Qed.

