  match r, ph with
  | 1, 0 => farm1_0_0RB1RC_0RC1RA_1LD1RB_0LA0LD
  | _, _ => farm1_0_0RB1RC_0RC1RA_1LD1RB_0LA0LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_0RB1RC_0RC1RA_1LD1RB_0LA0LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | _, _ => 0 end.
Definition fm2_0RB1RC_0RC1RA_1LD1RB_0LA0LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
