  | 1, (StB, S0) => [SWinR 1]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWinR 2]
  | 1, (StC, S1) => [SWin 0]
  | 1, (StD, S0) => [SWinR 3]
