(** ** What this board establishes

    80 of 84 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 84 of them
    collapse to 4 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    1 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_0RB1RD_1LC1RA_0LD0LC_0RA1RB : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [S1] 3 0 []) S1 (mkS [S1;S1;S1] [] 0 0 [])) (mkC StB (mkS [] [S1] 3 3 []) S1 (mkS [] [] 0 0 [])) 0 3, [RB (SWin 3);RB (SFoldL 1);RB (SFoldL 2)])].
Definition nrules_0RB1RD_1LC1RA_0LD0LC_0RA1RB : list LRule := map fst nlad_0RB1RD_1LC1RA_0LD0LC_0RA1RB.
Local Notation nrules := nrules_0RB1RD_1LC1RA_0LD0LC_0RA1RB.

Lemma nladder_ok_0RB1RD_1LC1RA_0LD0LC_0RA1RB : check_ladder tm [] nlad_0RB1RD_1LC1RA_0LD0LC_0RA1RB = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_0RB1RD_1LC1RA_0LD0LC_0RA1RB : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_0RB1RD_1LC1RA_0LD0LC_0RA1RB. Qed.

Definition iarm0_0_0RB1RD_1LC1RA_0LD0LC_0RA1RB : LRule :=
  mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [] [S1;S1;S1] 1 0 [S0;S0;S0]))
          (mkC StB (mkS [] [] 0 0 []) S1 (mkS [] [S0;S0;S0] 1 0 [S1;S1;S0])) 0 1.
Definition ch_iarm0_0_0RB1RD_1LC1RA_0LD0LC_0RA1RB : list nseg :=
  [NCh [RB (SCycR 3);RB (SWin 6);RB (SCycL 3 0);RB (SWinL 8)]].
Lemma ok_iarm0_0_0RB1RD_1LC1RA_0LD0LC_0RA1RB :
  check_narm tm true false nrules iarm0_0_0RB1RD_1LC1RA_0LD0LC_0RA1RB ch_iarm0_0_0RB1RD_1LC1RA_0LD0LC_0RA1RB = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm1_0_0RB1RD_1LC1RA_0LD0LC_0RA1RB : LRule :=
  mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]))
          (mkC StB (mkS [] [] 0 0 []) S1 (mkS [] [S0;S0;S0] 1 0 [S0;S0;S1])) 0 1.
