  [NUp 0 [] [S1;S1;S1] 0 1 0 (mkS [] [] 0 0 []) (mkS [] [] 0 0 []) true;
   NCh [RB (SWinR 6);RB (SCycL 1 0);RB (SWinL 8)]].
