  match r, ph with
  | 1, 0 => farm1_0_1RB0LC_1LC1RA_0RA1LD_0RA0LC
  | 2, 0 => farm2_0_1RB0LC_1LC1RA_0RA1LD_0RA0LC
  | _, _ => farm1_0_1RB0LC_1LC1RA_0RA1LD_0RA0LC  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB0LC_1LC1RA_0RA1LD_0RA0LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB0LC_1LC1RA_0RA1LD_0RA0LC (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 2, 0 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
