(** ** What this board establishes

    44 of 44 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 44 of them
    collapse to 4 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 2
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    2 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB0LC_1LC1RA_0RA1LD_0RD0LC : list (LRule * list rstep) :=
  [(mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [] [S0;S1] 1 0 [S0;S1;S1])) (mkC StC (mkS [] [] 0 0 []) S0 (mkS [] [S0;S1] 1 1 [S0])) 4 6, [RB (SRotR 1);RB (SWin 1);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 1);RB (SRotR 1);RB (SFoldR 1)]);
   (mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 [S1;S1])) (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 1 [])) 4 6, [RB (SWin 2);RB (SCycR 2);RB (SWin 2);RB (SCycL 2 0);RB (SWin 2);RB (SRotR 2);RB (SFoldR 1)])].
Definition nrules_1RB0LC_1LC1RA_0RA1LD_0RD0LC : list LRule := map fst nlad_1RB0LC_1LC1RA_0RA1LD_0RD0LC.
Local Notation nrules := nrules_1RB0LC_1LC1RA_0RA1LD_0RD0LC.

Lemma nladder_ok_1RB0LC_1LC1RA_0RA1LD_0RD0LC : check_ladder tm [] nlad_1RB0LC_1LC1RA_0RA1LD_0RD0LC = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB0LC_1LC1RA_0RA1LD_0RD0LC : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB0LC_1LC1RA_0RA1LD_0RD0LC. Qed.

Definition iarm0_0_1RB0LC_1LC1RA_0RA1LD_0RD0LC : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB0LC_1LC1RA_0RA1LD_0RD0LC : list nseg :=
  [NCh [RB (SWin 6)]].
Lemma ok_iarm0_0_1RB0LC_1LC1RA_0RA1LD_0RD0LC :
  check_narm tm true false nrules iarm0_0_1RB0LC_1LC1RA_0RA1LD_0RD0LC ch_iarm0_0_1RB0LC_1LC1RA_0RA1LD_0RD0LC = true.
