Qed.

Lemma bootl_1RB0LC_1LC1RA_0RB1LD_0RD0LC :
  stepn tm 45 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 45 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 45 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB0LC_1LC1RA_0RB1LD_0RD0LC : NeverQuasiHaltsTr tm_1RB0LC_1LC1RA_0RB1LD_0RD0LC.
