(** ** What this board establishes

    39 of 39 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 39 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    2 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB0LD_0LC0RA_1RA1LC_1LA0RB : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [] [S0;S1] 1 0 [S0;S1;S1])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [] [S0;S1] 1 1 [S0])) 4 8, [RB (SRotR 1);RB (SWin 3);RB (SCycR 2);RB (SWin 4);RB (SCycL 2 0);RB (SWin 1);RB (SRotR 1);RB (SFoldR 1)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [S0;S1] 1 0 [S1;S1])) (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S1] [S0;S1] 1 1 [])) 4 8, [RB (SWin 4);RB (SCycR 2);RB (SWin 2);RB (SCycL 2 0);RB (SWin 2);RB (SRotR 2);RB (SFoldR 1)])].
Definition nrules_1RB0LD_0LC0RA_1RA1LC_1LA0RB : list LRule := map fst nlad_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
Local Notation nrules := nrules_1RB0LD_0LC0RA_1RA1LC_1LA0RB.

Lemma nladder_ok_1RB0LD_0LC0RA_1RA1LC_1LA0RB : check_ladder tm [] nlad_1RB0LD_0LC0RA_1RA1LC_1LA0RB = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB0LD_0LC0RA_1RA1LC_1LA0RB : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB0LD_0LC0RA_1RA1LC_1LA0RB. Qed.

