Lemma farm_reach_1RB0LD_0LC0RA_1RA1LC_1LA0RB : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  ReachL tm true true (lr_lhs (farm_1RB0LD_0LC0RA_1RA1LC_1LA0RB r ph)) (lr_rhs (farm_1RB0LD_0LC0RA_1RA1LC_1LA0RB r ph)).
