Lemma vis_ok_1RB0LD_0LC0RA_1RA1LC_1LA0RB : forall r t, ~ In t pins_1RB0LD_0LC0RA_1RA1LC_1LA0RB -> 0 < r ->
  r < 1 + 1 ->
  nfire tm true true nrules (vsegs_1RB0LD_0LC0RA_1RA1LC_1LA0RB r t) (vis_1RB0LD_0LC0RA_1RA1LC_1LA0RB r t)
    (lr_lhs (farm_1RB0LD_0LC0RA_1RA1LC_1LA0RB r 0)) = Some t.
Proof.
  intros r t Hnp H0 Hr.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  exfalso; lia.
Qed.

Lemma bootl_1RB0LD_0LC0RA_1RA1LC_1LA0RB :
  stepn tm 21 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm 21 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 21 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** The machine-level theorem, at the INSTRUCTION level, through the nested
    board [LadderCheckNestTr.boardN_neverqhtr]. *)
Theorem nqhtr_1RB0LD_0LC0RA_1RA1LC_1LA0RB : NeverQuasiHaltsTr tm_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
Proof.
  eapply (boardN_neverqhtr tm_1RB0LD_0LC0RA_1RA1LC_1LA0RB pins_1RB0LD_0LC0RA_1RA1LC_1LA0RB FAM 1
                           iarm_1RB0LD_0LC0RA_1RA1LC_1LA0RB 1 1
                           farm_1RB0LD_0LC0RA_1RA1LC_1LA0RB 1 1
                           fm1_1RB0LD_0LC0RA_1RA1LC_1LA0RB fm2_1RB0LD_0LC0RA_1RA1LC_1LA0RB 0
                           nrules vsegs_1RB0LD_0LC0RA_1RA1LC_1LA0RB vis_1RB0LD_0LC0RA_1RA1LC_1LA0RB
                           [0] 0).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; lia. }
    exfalso; lia.
  - lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { exists 0; vm_compute; reflexivity. }
    exfalso; lia.
  - exact fm12_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - repeat constructor.
  - vm_compute; lia.
  - lia.
  - lia.
  - exact iarm_reach_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - exact iarm_lhs_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - exact iarm_rhs_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - lia.
  - lia.
  - exact farm_reach_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - exact farm_lhs_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - exact farm_rhs_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - exact nrules_sound_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - exact vis_ok_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
  - exact bootl_1RB0LD_0LC0RA_1RA1LC_1LA0RB.
Qed.

